/* eslint-disable no-console */
import cssnano from 'cssnano'
import * as fs from 'fs'
import postcss from 'postcss'
import * as sass from 'sass'

const INPUT_SCSS = 'theme.scss'
const OUTPUT_TS = 'src/styles.generated.ts'

async function generateStyles (): Promise<void> {
  const css = sass.compile(INPUT_SCSS).css
  const minified = (await postcss([cssnano({ preset: 'default' })]).process(css, { from: undefined })).css

  const content = [
    '// Generated by buildEnv.ts from theme.scss. Do not edit.',
    `export const CSS = ${JSON.stringify(minified)}`,
    '',
  ].join('\n')

  fs.writeFileSync(OUTPUT_TS, content, 'utf-8')
  console.log(`Updated ${OUTPUT_TS} (${Buffer.byteLength(minified)} bytes)`)
}

generateStyles().catch((error) => {
  console.error(error)
  process.exitCode = 1
})
